function testInventory(uid){
  if(testSession&&uid!==TEST_UID){SAVE=testSession.base;testSession=null;G=null;if(typeof buildMenu==='function')buildMenu()}
  if(uid!==TEST_UID||testSession)return;
  const base=SAVE,copy=JSON.parse(JSON.stringify(base));
  copy.lt=999999999;
  // Permanent realm perk on the RAM clone only; preserve herbs, pills and future fields.
  copy.alchemy=Object.assign({version:1,herb:0,pills:[0,0,0,0,0]},copy.alchemy,{level:45});
  copy.gear={items:[],eq:{},nid:1};
  for(const k of GEAR_KEYS)for(let r=0;r<GRAR.length;r++)copy.gear.items.push({id:copy.gear.nid++,k,r,lv:GRAR[r].max});
  copy.mat=Object.assign({},copy.mat,{thao:999999,thiet:999999});
  copy.pet=Object.assign({eq:'linhho'},copy.pet,{lv:Object.assign({},copy.pet?.lv)});
  for(const k of PET_KEYS)copy.pet.lv[k]=PET_MAX;
  copy.pnPets=Object.assign({},copy.pnPets,{eggs:999,medicine:999});
  const realm=REALMS.length-1,level=REALMS[realm].lv;
  copy.bestLv=Math.max(copy.bestLv||0,level);copy.bestRealm=Math.max(copy.bestRealm||0,realm);
  copy.pnt=Object.assign({},copy.pnt,{level,realm});
  // Even direct JSON.stringify(SAVE) exports the original, unboosted snapshot.
  Object.defineProperty(copy,'toJSON',{enumerable:false,value:()=>base});
  testSession={base};SAVE=copy;
  if(typeof buildMenu==='function')buildMenu();
}
