const originalSave=saveSave,rawSave=function(){if(!testSession)return originalSave.apply(this,arguments)},runs=new WeakMap(),chests=new WeakSet();
const QUESTS=[['kills','Trừ yêu nhập môn',20,50,true],['time','Tu luyện 60 giây',60,50,false],['level','Đạt cấp 3 trong trận',3,50,false],['chat','Gửi 1 truyền âm',1,50,false],['spin','Quay thưởng 1 lần',1,50,false],['checkin','Điểm danh hôm nay',1,50,false]],qtimes=new WeakMap();
function questDay(){const s=S(),day=DAY();if(!s.quests||s.quests.day!==day)s.quests={day,progress:{},claimed:{}};if(dayState?.day===day){s.quests.progress.checkin=Math.max(N(s.quests.progress.checkin),dayState.checkin?1:0);s.quests.progress.spin=Math.max(N(s.quests.progress.spin),N(dayState.spinCount))}return s.quests}
function questAdd(k,n){if(!user||n<=0)return;const q=questDay();q.progress[k]=N(q.progress[k])+n}
function questSample(){if(!user||!G)return;const q=questDay(),now=N(G.t),prev=qtimes.get(G);if(prev!==undefined)questAdd('time',Math.max(0,now-prev));qtimes.set(G,now);q.progress.level=Math.max(N(q.progress.level),N(G.lv))}
function claimQuest(id){if(!user){open('account');return}sample();const q=questDay(),a=QUESTS.find(x=>x[0]===id);if(!a||q.claimed[id]||N(q.progress[id])<a[2])return;if(a[4]&&gearSave().items.length>=80){say('Kho đủ 80 trang bị; hãy dọn một ô trước khi nhận.');return}if(a[4])addGear(pick(['thanhphong','vanvan','phongthan']),0);q.claimed[id]=true;SAVE.lt=N(SAVE.lt)+a[3];persist();toast('Nhiệm vụ +'+a[3]+' linh thạch'+(a[4]?' · +1 trang bị Phàm cấp 1':''));render()}
