const BOARDS=[['realm','Cảnh Giới','Thiên Hạ Đệ Nhất'],['money','Linh Thạch','Vạn Bảo Tiên Quân'],['pets','Linh Sủng','Vạn Thú Chí Tôn']],TITLE_TTL=86400000;
let board='realm',profilesReady=false,rankPublished=false,awardBusy=false;
function realSave(){return testSession?.base||SAVE}
function rankMetrics(s){const levels=Object.values(s.pet?.lv||{}).map(N).filter(n=>n>0);return {alchemyLevel:Math.max(1,N(s.alchemy?.level)),wallet:N(s.lt),petTotalLevel:levels.reduce((a,b)=>a+b,0),petCount:levels.length}}
function rankList(key,rows=players){return rows.filter(x=>Number.isFinite(x.alchemyLevel)).slice().sort((a,b)=>(key==='realm'?N(b.alchemyLevel)-N(a.alchemyLevel):key==='money'?N(b.wallet)-N(a.wallet):N(b.petTotalLevel)-N(a.petTotalLevel)||N(b.petCount)-N(a.petCount))||String(a.uid).localeCompare(String(b.uid),'en'))}
function activeRankTitle(p,now=Date.now()){const i=BOARDS.findIndex(b=>b[0]===p?.rankTitleId),t=Number(p?.rankTitleAwardedAt);return i>=0&&t>0&&t<=now&&now-t<TITLE_TTL?BOARDS[i]:null}
function playerBadge(id,p){const profile=players.find(x=>x.uid===p?.uid)||p,t=activeRankTitle(profile);if(!t)return badge(id);const e=el('span',' ‹'+t[2]+'›','pn-badge pn-epic pn-title-'+t[0]);const lv=N(profile.alchemyLevel),tier=Math.max(0,REALMS.findLastIndex(r=>r.lv<=lv));e.style.color=C[Math.min(7,tier)];return e}
async function awardRankTitle(){if(!user||!profilesReady||!rankPublished||awardBusy)return;const own=players.find(x=>x.uid===user.uid);if(!own)return;const active=activeRankTitle(own),win=BOARDS.find(b=>rankList(b[0])[0]?.uid===user.uid);let id=active?own.rankTitleId:'',at=active?own.rankTitleAwardedAt:0;if(win&&(!active||BOARDS.indexOf(win)<BOARDS.indexOf(active))){id=win[0];at=Date.now()}if(id===(own.rankTitleId||'')&&at===(own.rankTitleAwardedAt||0))return;awardBusy=true;try{await sdk.F.setDoc(sdk.F.doc(db,'pnt_players',user.uid),{rankTitleId:id,rankTitleAwardedAt:at},{merge:true})}catch(e){say('Danh hiệu BXH: '+err(e))}finally{awardBusy=false}}
function rankIcon(n){const e=el('span','#'+n+' ');e.className='pn-rank-icon';if(n>10)return e;const color=n===1?'#ffd678':n===2?'#bbcbd6':n===3?'#c58b55':'#f1c453';e.innerHTML='<svg width="20" height="20" viewBox="0 0 24 24" aria-hidden="true" style="vertical-align:middle"><path fill="'+color+'" d="'+(n===1?'M2 5l5 4 5-7 5 7 5-4-3 14H5z':n===2?'M12 1l10 11-10 11L2 12z':n===3?'M12 1l10 6v10l-10 6-10-6V7z':'M12 2l3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z')+'"/><path fill="#19344B" d="M9 9h6v7H9z"/></svg> #'+n+' ';return e}
function renderRanks(B){const tabs=el('div',undefined,'ktabs');tabs.style.cssText='display:flex;gap:4px;flex-wrap:nowrap;width:100%;margin-bottom:8px';tabs.setAttribute('role','tablist');for(const [key,label] of BOARDS){const b=btn(label,()=>{board=key;render()});b.dataset.t=key;b.classList.toggle('on',board===key);b.setAttribute('role','tab');b.setAttribute('aria-selected',String(board===key));b.style.cssText='flex:1;min-width:0;padding:6px 2px;font-size:13px';tabs.append(b)}B.append(tabs,el('small',board==='realm'?'Đột Phá vĩnh viễn · đồng hạng: UID cố định.':board==='money'?'Ví linh thạch hiện có · đồng hạng: UID cố định.':'Tổng cấp linh sủng sở hữu → số linh sủng → UID cố định.'));const sorted=rankList(board),own=sorted.findIndex(x=>x.uid===user.uid);B.append(el('p',own>=0?'Hạng của bạn: #'+(own+1):'Chờ hồ sơ đồng bộ bản mới…'));const list=sorted.slice(0,50);if(own>=50)list.push(sorted[own]);for(const x of list){const r=row(),n=sorted.indexOf(x)+1;r.dataset.rank=n;r.dataset.board=board;if(x.uid===user.uid)r.classList.add('pn-me');const head=el('b');head.append(rankIcon(n),playerBadge(x.titleId,x),document.createTextNode(x.name||'Đạo hữu'));r.append(head);const lv=N(x.alchemyLevel),tier=Math.max(0,REALMS.findLastIndex(r=>r.lv<=lv)),text=board==='realm'?REALMS[tier].n+' · bậc '+lv:board==='money'?N(x.wallet).toLocaleString('vi-VN')+' linh thạch':N(x.petTotalLevel)+' tổng cấp · '+N(x.petCount)+' linh sủng';r.append(el('p',text));B.append(r)}B.append(el('small','Top 1 mỗi bảng nhận danh hiệu 24h; ưu tiên Cảnh Giới > Linh Thạch > Linh Sủng. Hồ sơ cũ chờ chủ nhân online đồng bộ; BXH client tự khai báo.'),btn('Cập nhật BXH',async()=>{try{if(Date.now()-lastRank<5000)return;await publishRank();lastRank=Date.now();await awardRankTitle();render()}catch(e){say(err(e))}}))}


const epicStyle=el('style');epicStyle.textContent="\n/* Prestige titles: bounded CSS-only layers; text keeps its permanent-realm color. */\n.pn-epic{position:relative;display:inline-block;isolation:isolate;max-width:100%;padding:1px 4px;vertical-align:middle;overflow:hidden;overflow-wrap:anywhere;text-shadow:0 1px 2px #000,0 0 5px var(--pn-a);font-weight:800;line-height:1.5}\n.pn-epic::before,.pn-epic::after{content:'';position:absolute;pointer-events:none;inset:0;z-index:-1;border-radius:3px}\n.pn-epic::before{background:radial-gradient(ellipse at 15% 100%,var(--pn-a),transparent 45%),radial-gradient(ellipse at 80% 110%,var(--pn-b),transparent 55%);opacity:.35;animation:pn-title-fire 1.8s ease-in-out infinite alternate}\n.pn-epic::after{background:linear-gradient(100deg,transparent 5%,var(--pn-a) 48%,transparent 53%);opacity:.3;clip-path:polygon(0 90%,20% 60%,30% 80%,50% 15%,58% 57%,80% 30%,100% 0,85% 55%,68% 65%,55% 90%,46% 55%,30% 100%);animation:pn-title-spark 2.6s steps(1,end) infinite}\n.pn-title-realm{--pn-a:#ffd678;--pn-b:#6aafe0}.pn-title-realm::before{animation-duration:2.4s}.pn-title-money{--pn-a:#f1c453;--pn-b:#ed793f}.pn-title-money::after{animation-delay:.7s}.pn-title-pets{--pn-a:#78c69d;--pn-b:#b294ee}.pn-title-pets::before{animation-duration:2.1s}.pn-title-pets::after{animation-delay:1.3s}\n@keyframes pn-title-fire{from{transform:translateY(2px) scaleX(.96);opacity:.25}to{transform:translateY(-2px) scaleX(1.04);opacity:.55}}\n@keyframes pn-title-spark{0%,15%,24%,100%{opacity:0;transform:translateX(-4px)}16%,25%{opacity:.75;transform:translateX(2px)}18%,27%{opacity:.2;transform:translateX(0)}}\n.pn-fx-paused .pn-epic::before,.pn-fx-paused .pn-epic::after{animation-play-state:paused}\n@media(prefers-reduced-motion:reduce){.pn-epic::before,.pn-epic::after{animation:none!important;opacity:.25}}\n";document.head.append(epicStyle);addEventListener('visibilitychange',()=>document.body.classList.toggle('pn-fx-paused',document.hidden));
