css.textContent+="\n/* Horizontal lobby overlay; no lobby reflow. */\n#pn-game-head{position:fixed!important;left:8px!important;right:8px!important;top:110px!important;transform:none!important;width:auto!important;max-width:none!important;max-height:none!important;padding:0!important;z-index:70}\n#pn-dock,#pn-dock.collapsed{position:relative!important;inset:auto!important;width:100%;min-width:0;max-width:100%;background:#0B1B2A!important;color:#ffd678!important;border:2px solid #19344B;border-radius:4px;padding:5px;box-shadow:0 3px 0 #0005;font-family:'Baloo 2',sans-serif}\n#pn-dock::before{display:none!important}#pn-game-head #pn-dock:not(.collapsed){border:22px solid transparent!important;border-image:url(assets/ui_panel.webp) 92/22px!important;border-radius:0;padding:0 3px 3px;filter:drop-shadow(0 8px 0 rgba(0,0,0,.35));box-shadow:none}#pn-game-head #pn-dock.collapsed{border:0!important;border-image:none!important;filter:none}#pn-game-head #pn-dock #pn-toggle{background:#11263A!important;color:#ffd678!important;border:11px solid transparent!important;border-left-width:20px!important;border-right-width:20px!important;border-image:url(assets/ui_plaque.webp) 50 62/11px 20px!important;height:auto!important;min-height:40px!important;padding:1px 2px!important;border-radius:0;font-family:'Baloo 2',sans-serif!important}\n#pn-dock header{display:flex!important;justify-content:flex-end;height:auto;min-height:32px}\n#pn-dock header strong,#pn-status-dock{display:none!important}\n#pn-dock #pn-toggle{width:auto!important;height:32px;min-height:32px!important;padding:4px 10px!important;background:#11263A;color:#ffd678;border:1px solid #19344B;font:800 14px 'Baloo 2',sans-serif}\n#pn-dock nav{visibility:visible;pointer-events:auto;display:flex!important;flex-flow:row wrap!important;overflow-x:hidden!important;overflow-y:visible!important;max-height:none!important;gap:5px;margin-top:4px;scrollbar-width:none;touch-action:manipulation}\n#pn-dock nav button{flex:0 0 auto;display:flex!important;flex-direction:column;justify-content:center;gap:4px;min-width:72px;min-height:56px!important;padding:5px!important;background:#11263A;color:#ffd678!important;font:700 12px/1.2 'Baloo 2',sans-serif!important;white-space:nowrap}\n#pn-dock nav button svg,#pn-dock nav button img{width:24px;height:24px;background:#19344B}\n#pn-dock nav button:hover,#pn-dock nav button:focus-visible{background:#19344B;color:#f1c453}\n#pn-dock.collapsed{width:fit-content;margin-left:auto;background:transparent!important;border:0;box-shadow:none;padding:0}\n#pn-dock.collapsed nav{display:none!important;visibility:hidden;pointer-events:none}\n#pn-modal .pn-card:not(:has(.pn-chat-body)){background:#0B1B2A!important;color:#ffd678!important;border-image:none!important;border:2px solid #19344B!important;font-family:'Baloo 2',sans-serif}\n#pn-modal .pn-card:not(:has(.pn-chat-body))>h2.pn-native-title{background:#19344B!important;color:#ffd678!important;border:11px solid transparent!important;border-left-width:20px!important;border-right-width:20px!important;border-image:url(assets/ui_plaque.webp) 50 62/11px 20px!important;font-family:'VT323',monospace}\n#pn-modal .pn-row{background:#11263A!important;color:#ffd678!important;border-color:#19344B!important}\n#pn-modal #pn-log>div>b,#pn-latest span>b{font-weight:900;text-shadow:0 0 .35px currentColor}\n#pn-modal #pn-log>div>p,#pn-latest .pn-chat-text{color:#244c68;font-weight:500}\n";const dock=el('aside');dock.id='pn-dock';dock.setAttribute('aria-label','Sự kiện và trực tuyến');dock.innerHTML='<header><strong>✦ Sự Kiện</strong><span id="pn-status-dock"></span><button type="button" id="pn-toggle" aria-label="Thu gọn sự kiện">−</button></header><nav></nav>';document.body.append(dock);
const taskStack=el('section');taskStack.id='pn-task-stack';const latest=btn('',()=>open('chat'));latest.id='pn-latest';latest.className='spx';latest.innerHTML='<strong>TRUYỀM ÂM</strong><span>Chưa có truyền âm.</span>';const task=$('sanhQ');if(task){task.before(taskStack);taskStack.append(latest,task)}
function latestChat(){const m=[...messages.values()].sort((a,b)=>b.ms-a.ms)[0],box=latest.querySelector('span');box.replaceChildren();if(!m){box.textContent='Chưa có truyền âm.';return}box.append(playerBadge(m.titleId,m),el('b',m.name+': '));const a=/^\[s:([a-z]+)\]$/.exec(m.text||'');if(a&&Object.hasOwn(STICKERS,a[1]))box.append(sticker(a[1],24));else box.append(el('span',m.text||'','pn-chat-text'))}
const head=el('section');head.id='pn-game-head';const top=$('sanhTop'),lobby=$('menu');if(top){top.after(head);head.append(dock)}else{lobby.querySelector('.card')?.prepend(dock)}

const modal=el('div');modal.id='pn-modal';modal.className='screen bg';modal.hidden=true;modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','pn-heading');modal.innerHTML='<section class="pn-card card"><h2 class="pn-native-title"><span id="pn-heading"></span><button type="button" id="pn-close" aria-label="Đóng sự kiện">×</button></h2><div id="pn-status" role="status"></div><main id="pn-body"></main></section>';document.body.append(modal);
