if(page==='daily'){B.append(el('p','Chu kỳ 7 lần điểm danh, không cần liên tiếp. Một lần/ngày UTC, đổi ngày lúc 07:00 Việt Nam. Đồng bộ trạng thái nhận, không đồng bộ toàn bộ tiền/save giữa thiết bị.'));const grid=el('div',undefined,'pn-grid');DAILY.forEach((v,i)=>grid.append(row('Ngày '+(i+1)+' · '+v+' ◈'+(i===totalDays%7?' ◀':''))));const b=btn(dayState?.checkin?'Hôm nay đã nhận':'Nhận điểm danh',()=>eventClaim('daily'));b.disabled=busy||!!dayState?.checkin;B.append(grid,b);return}
