if(page==='chat'){$('pn-body').classList.add('pn-chat-body');const log=el('div');log.id='pn-log';log.setAttribute('aria-label','Tin nhắn thế giới');B.append(log);chatLog();const f=el('form');f.className='pn-composer';f.innerHTML='<label>Tin nhắn (1–200 ký tự)<input id="pn-message" maxlength="200" autocomplete="off" required></label><button class="btn" type="submit" aria-label="Gửi truyền âm"><svg width="20" height="20" viewBox="0 0 16 16" aria-hidden="true" shape-rendering="crispEdges"><path fill="#6aafe0" d="M1 6h3V5h3V4h3V3h5v3h-1v3h-1v3h-1v3H9v-4H6V9H1z"/><path fill="#fff2d2" d="M4 7h5V6h3v2H9v2H7V9H4z"/><path fill="#f1c453" d="M3 11h2v2H3zm-2 2h2v2H1z"/></svg> Gửi</button>';const picker=el('div',undefined,'pn-stickers card');picker.hidden=true;picker.setAttribute('aria-label','Sticker');picker.style.cssText='display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:8px 0;padding:12px';picker.style.display='none';const toggle=btn('☺',()=>{picker.hidden=!picker.hidden;picker.style.display=picker.hidden?'none':'grid'});toggle.setAttribute('aria-label','Chọn sticker');toggle.replaceChildren(sticker('smile',24));f.append(toggle);for(const [code,label] of Object.entries(STICKERS)){const b=btn('',async()=>{if(await sendTransmission('[s:'+code+']')){picker.hidden=true;picker.style.display='none'}});b.setAttribute('aria-label',label);b.title=label;b.append(sticker(code,40));picker.append(b)}f.onsubmit=async e=>{e.preventDefault();const input=$('pn-message'),text=input.value.trim(),b=f.querySelector('button[type=submit]');b.disabled=true;try{if(await sendTransmission(text))input.value=''}finally{b.disabled=false}};B.append(f,picker,el('small','Firestore onSnapshot · tối đa 200 tin trong phiên. Máy chủ lưu tin mới nhất mỗi UID; tải lại không khôi phục toàn bộ lịch sử.'));return}
