function matchTheme(){modal.querySelector('.pn-card').classList.add('card');modal.querySelectorAll('button').forEach(b=>b.classList.add('btn'));$('pn-status').classList.add('sub');modal.querySelectorAll('.pn-row').forEach(r=>r.classList.add('chr'));}

const STICKERS={smile:'Mỉm cười',lol:'Cười lớn',wink:'Nháy mắt',cry:'Khóc',angry:'Giận',cool:'Kính mát',sleepy:'Buồn ngủ',tongue:'Lè lưỡi',love:'Yêu thích',wow:'Ngạc nhiên',sad:'Buồn',kiss:'Gửi nụ hôn'};
function sticker(code,size=56){if(!Object.hasOwn(STICKERS,code))return el('span','Sticker không hợp lệ');const e=document.createElementNS('http://www.w3.org/2000/svg','svg');e.setAttribute('viewBox','0 0 64 64');e.setAttribute('width',size);e.setAttribute('height',size);e.setAttribute('role','img');e.setAttribute('aria-label',STICKERS[code]);let eyes='<ellipse cx="22" cy="26" rx="3" ry="5"/><ellipse cx="42" cy="26" rx="3" ry="5"/>',mouth='<path d="M19 38q13 16 26 0" fill="#fff3ca" stroke="#64351d" stroke-width="3"/>';
if(['lol','sleepy'].includes(code))eyes='<path d="M16 26q6-7 12 0m8 0q6-7 12 0" fill="none" stroke="#64351d" stroke-width="3"/>';
if(code==='wink')eyes='<path d="M16 26q6-6 12 0" fill="none" stroke="#64351d" stroke-width="3"/><ellipse cx="42" cy="26" rx="3" ry="5"/>';
if(code==='cool')eyes='<path fill="#19344B" d="M12 20h18v14H15zm22 0h18l-3 14H34zM28 23h8v4h-8z"/><path stroke="#bbcbd6" stroke-width="2" d="m17 23 7 7m15-7 7 7"/>';
if(code==='love')eyes='<path fill="#e95b56" d="M12 23q0-10 9-4q9-6 9 4l-9 11zm22 0q0-10 9-4q9-6 9 4l-9 11z"/>';
if(code==='angry')eyes+='<path stroke="#64351d" stroke-width="4" d="m14 17 15 5m6 0 15-5"/>';
if(['cry','sad','angry'].includes(code))mouth='<path d="M20 45q12-14 24 0" fill="none" stroke="#64351d" stroke-width="3"/>';
if(['wow','sleepy'].includes(code))mouth='<ellipse cx="32" cy="43" rx="6" ry="8" fill="#64351d"/>';
if(code==='lol')mouth='<path d="M17 36h30q-2 22-15 20T17 36" fill="#64351d"/><path d="M20 37h24v5H20" fill="white"/><ellipse cx="32" cy="51" rx="8" ry="4" fill="#e95b56"/>';
if(code==='tongue')mouth='<path d="M18 38q14 14 28 0" fill="none" stroke="#64351d" stroke-width="3"/><path d="M31 42h12v10q-7 9-12 0z" fill="#e95b56"/>';
if(code==='kiss')mouth='<path d="m29 37 8 5-8 5 8 5" fill="none" stroke="#64351d" stroke-width="3"/>';
const extra=code==='cry'?'<path d="M18 31q-10 14-1 14t1-14m28 0q-10 14-1 14t1-14" fill="#6aafe0"/>':code==='sleepy'?'<text x="43" y="16" font-size="13" fill="#6aafe0">Zz</text>':'';
e.innerHTML='<circle cx="32" cy="33" r="29" fill="#cf8c22"/><circle cx="32" cy="30" r="28" fill="#ffd34f" stroke="#9c6023" stroke-width="2"/><path d="M12 21Q18 6 36 7" fill="none" stroke="#fff2ad" stroke-width="5" stroke-linecap="round"/><g fill="#64351d">'+eyes+mouth+'</g>'+extra;return e}
function messageBody(m){const match=/^\[s:([a-z]+)\]$/.exec(m.text||'');return match&&Object.hasOwn(STICKERS,match[1])?sticker(match[1]):el('p',String(m.text||''))}
async function sendTransmission(text){if(!user||busy)return false;if(!text||text.length>200)return false;const match=/^\[s:([^\]]+)\]$/.exec(text);if(match&&!Object.hasOwn(STICKERS,match[1])){say('Sticker không hợp lệ.');return false}if(Date.now()-lastSent<2500){say('Chờ ít nhất 2,5 giây giữa hai tin.');return false}busy=true;lastSent=Date.now();try{const s=S();await sdk.F.setDoc(sdk.F.doc(db,'pnt_chat',user.uid),{uid:user.uid,name:name(),level:Math.min(100000,N(s.level)),realm:R[Math.min(7,N(s.realm))],titleId:equipped(),text,t:sdk.F.serverTimestamp()});questAdd('chat',1);persist();say('Đã gửi truyền âm.');return true}catch(e){say('Gửi truyền âm: '+err(e));return false}finally{busy=false}}

function chatLog(){latestChat();const log=$('pn-log');if(!log)return;const near=log.scrollHeight-log.scrollTop-log.clientHeight<50;log.replaceChildren();for(const m of [...messages.values()].sort((a,b)=>a.ms-b.ms)){const r=el('div');r.append(playerBadge(m.titleId,m),el('b',m.name),el('small',' · '+new Date(m.ms).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})),messageBody(m));log.append(r)}if(near||!log.scrollTop)log.scrollTop=log.scrollHeight}
let ticks=0;setInterval(()=>{sample();if(++ticks%5===0)rawSave();layout();if(!modal.hidden&&page==='online')render()},1000);addEventListener('pagehide',persist);addEventListener('online',()=>{if(user)heartbeat()});collapse();persist();say(notice);document.body.classList.add('pn-locked');open('account');addEventListener('keydown',e=>{if(!user&&!modal.contains(e.target)){e.preventDefault();e.stopImmediatePropagation()}},true);
if(typeof newRun==='function'){const run=newRun;newRun=function(){if(!user){open('account');return}const result=run.apply(this,arguments);testRun();return result}}if(typeof update==='function'){const step=update;update=function(){if(user)return step.apply(this,arguments)}};

